static void lm_compile_wr4(uint32_t v){
  unsigned char h[4]={(unsigned char)v,(unsigned char)(v>>8),(unsigned char)(v>>16),(unsigned char)(v>>24)};
  fwrite(h,1,4,stdout);
}
